// ResourceRecorder selects and constructs one envelope for both publication paths.
// Install it in place of WatchRecorder + OutboxRecorder. Audit stays separate.
func ResourceRecorder(w *watch.Watch, outbox bool, selectEvent resource.Select, options resource.RecorderOptions) bare.Recorder {
	return resourceRecorder{w, outbox, selectEvent, options}
}

type resourceRecorder struct {
	w           *watch.Watch
	outbox      bool
	selectEvent resource.Select
	options     resource.RecorderOptions
}

// Snapshots requests only images this publisher uses; ordinary audit recorders
// need none. Deletes retain their only image for historical authorization.
func (r resourceRecorder) Snapshots(method string) bare.SnapshotOptions {
	switch resourceChangeKind(method) {
	case pdpb.ChangeKind_CHANGE_KIND_CREATED:
		return bare.SnapshotOptions{Value: true}
	case pdpb.ChangeKind_CHANGE_KIND_UPDATED:
		return bare.SnapshotOptions{Value: true, Previous: r.options.Previous}
	case pdpb.ChangeKind_CHANGE_KIND_DELETED:
		return bare.SnapshotOptions{Previous: true}
	default:
		return bare.SnapshotOptions{}
	}
}
func resourceChangeKind(method string) pdpb.ChangeKind {
	switch method {
	case page.AuditService_Add_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_CREATED
	case page.AuditService_Patch_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_UPDATED
	case page.AuditService_Apply_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_UPDATED
	case page.AuditService_Erase_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_DELETED
	case page.HolderService_Add_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_CREATED
	case page.HolderService_Patch_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_UPDATED
	case page.HolderService_Apply_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_UPDATED
	case page.HolderService_Erase_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_DELETED
	case page.TenantService_Add_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_CREATED
	case page.TenantService_Patch_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_UPDATED
	case page.TenantService_Apply_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_UPDATED
	case page.TenantService_Erase_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_DELETED
	case page.ThingService_Add_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_CREATED
	case page.ThingService_Patch_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_UPDATED
	case page.ThingService_Apply_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_UPDATED
	case page.ThingService_Erase_FullMethodName:
		return pdpb.ChangeKind_CHANGE_KIND_DELETED
	default:
		return pdpb.ChangeKind_CHANGE_KIND_UNSPECIFIED
	}
}
func (r resourceRecorder) Record(ctx context.Context, s bare.Server, c bare.Change) error {
	kind := resourceChangeKind(c.By)
	previous := c.Previous
	if kind == pdpb.ChangeKind_CHANGE_KIND_UPDATED && !r.options.Previous {
		previous = nil
	}
	image := c.Value
	if image == nil {
		image = c.Previous
	}
	if image == nil {
		return nil
	}
	switch image.ProtoReflect().Descriptor().FullName() {
	case "app.Access", "app.Audit", "app.Deployment", "app.Holder", "app.Site", "app.Tenant", "app.Thing":
	default:
		return nil
	}
	k, err := pdid.From(keyBytes(c.Key))
	if err != nil {
		return err
	}
	id := pdid.New(OutboxDomain)
	at := time.Now().UTC()
	event, err := resource.Event(id[:], at, c.Method, watch.CallMethod(ctx, c.Method), kind, publicResource(previous), publicResource(c.Value))
	if err != nil {
		return err
	}
	if r.selectEvent != nil {
		ok, err := r.selectEvent(ctx, proto.Clone(event).(*pdpb.WatchEvent))
		if err != nil || !ok {
			return err
		}
	}
	doc := []byte{}
	if v := hidden(k, c.Patch); v != nil {
		doc, err = proto.Marshal(v)
		if err != nil {
			return err
		}
	}
	if r.outbox {
		data, err := proto.Marshal(event)
		if err != nil {
			return err
		}
		var actor, tenant pdid.Id
		if f, ok := frame.From(ctx); ok {
			actor = f.Actor
			tenant = f.Tenant
		}
		if err := s.Db.Outbox.Create().SetId(id.Uuid()).SetDateCreated(at).SetActorId(actor.Uuid()).SetTenantId(tenant.Uuid()).SetMethod(c.Method).SetBy(c.By).SetObjectId(k.Uuid()).SetPatch(doc).SetEvent(data).Exec(ctx); err != nil {
			return err
		}
	}
	if r.w != nil {
		r.w.Note(ctx, watch.Change{Method: c.Method, By: c.By, Key: k, Patch: doc, Resource: event})
	}
	return nil
}
